#include "../src/AlphaSimulation.h"
#include "../src/CampaignFiles.h"
using namespace alpha;
int checks=0;void check(bool ok,const char* msg){if(!ok)throw std::runtime_error(msg);++checks;std::cout<<"PASS "<<msg<<std::endl;}
void write(World& w,const std::filesystem::path& file){std::filesystem::create_directories(file.parent_path());std::ofstream out(file);out<<"FRONTIERE_CAMPAIGN 1\n500 900 1\n";w.save(out);out.close();check(bool(out),"test world written as real campaign save");}
int main(){try{
 auto temp=std::filesystem::current_path()/("slots-test-"+std::to_string(GetCurrentProcessId()));SetEnvironmentVariableW(L"FRONTIERE_DATA_DIR",temp.c_str());campaignFiles::select("");
 World w;w.startLegacyMission(2);write(w,campaignFiles::autoPath());campaignFiles::progress(3);auto old=campaignFiles::autoPath();check(campaignFiles::records().size()==1&&campaignFiles::records()[0].legacy,"pre-existing campaign remains discoverable");
 check(campaignFiles::create(0),"first new campaign created");auto human=campaignFiles::activeSlot();w.startLegacyMission(3,0);write(w,campaignFiles::autoPath());campaignFiles::progress(4);check(campaignFiles::create(1),"second new campaign created");auto dark=campaignFiles::activeSlot();check(human!=dark&&campaignFiles::progress()==0,"new slots have independent identity and progress");w.startLegacyMission(8,1);write(w,campaignFiles::savePath());campaignFiles::progress(9);auto darkSave=campaignFiles::savePath();auto records=campaignFiles::records();check(records.size()==3,"legacy human and dark campaigns all listed");
 bool foundHuman=false,foundDark=false;for(auto& r:records){if(r.id==human)foundHuman=r.faction==0&&r.mission==3;if(r.id==dark)foundDark=r.faction==1&&r.mission==8;}check(foundHuman&&foundDark,"list reports actual saved race and mission");
 campaignFiles::select(human);check(campaignFiles::progress()==4&&campaignFiles::autoPath()!=old&&campaignFiles::autoPath()!=darkSave,"human slot retains progress and separate paths");campaignFiles::select(dark);check(campaignFiles::progress()==9,"dark slot retains its own progress");auto selected=campaignFiles::activeSlot();check(!campaignFiles::select("../escape")&&campaignFiles::activeSlot()==selected,"slot selection rejects traversal without changing active slot");
 {std::ofstream out(campaignFiles::autoPath());out<<"BROKEN";}check(campaignFiles::continuePath()==darkSave,"corrupt latest autosave falls back to valid manual save");check(campaignFiles::records().size()==3,"corrupt autosave never hides recoverable campaign");campaignFiles::select("");check(campaignFiles::progress()==3&&std::filesystem::exists(old),"new campaigns never overwrite legacy progress or save");
 for(int f=0;f<2;++f)for(int n=0;n<missionCount;++n){w.startLegacyMission(n,f);check(w.faction[0]==f&&w.faction[1]==1-f,"all missions initialize both chosen factions");for(auto& e:w.entities)if(e.team>=0&&e.hp>0&&(e.kind==Kind::Mage||e.kind==Kind::Warlock))check(w.factionAllows(e.kind,e.team),"preplaced casters match their owning faction");std::ostringstream out;w.save(out);World copy;std::istringstream in(out.str());check(copy.restore(in)&&copy.faction[0]==f,"all faction scenarios persist in saved games");}
 w.startLegacyMission(8,1);w.townLevel[0]=3;w.add(Kind::Academy,0,{450,500});w.upgrades[0][int(Research::Arcana)]=1;w.add(Kind::Warlock,0,{450,1000});w.add(Kind::Warlock,0,{490,1000});w.updateMission(.05f);check(w.missionStage==1,"dark ninth mission accepts summoners instead of unattainable human mages");
 w.startLegacyMission(8,1);w.cheat("upgrade all");w.cheat("unlock on");int academy=w.add(Kind::Academy,0,{450,700});check(!w.train(academy,Kind::Mage),"dark academy cannot train human mage even with unlock cheat");check(w.train(academy,Kind::Warlock),"dark academy can train own summoner");
 std::cout<<"SUCCESS "<<checks<<" faction campaign and save slot checks"<<std::endl;return 0;
 }catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<std::endl;return 1;}}
